from collections import OrderedDict

def lru_run(capacity, ops):
    c = OrderedDict()
    out = []
    for op in ops:
        if op[0] == 'put':
            k, v = op[1], op[2]
            if k in c:
                c.move_to_end(k)
            c[k] = v
            if len(c) > capacity:
                c.popitem(last=False)
        else:
            k = op[1]
            if k in c:
                c.move_to_end(k)
                out.append(c[k])
            else:
                out.append(-1)
    return out

